import sys

def add(a, b):
    i, j = len(a), len(b)
    carry = 0
    parts = []
    while i > 0 or j > 0 or carry:
        x = int(a[max(0, i - 4):i]) if i > 0 else 0
        y = int(b[max(0, j - 4):j]) if j > 0 else 0
        i = max(0, i - 4)
        j = max(0, j - 4)
        s = x + y + carry
        carry = s // 10000
        parts.append(s % 10000)
    return str(parts[-1]) + ''.join('%04d' % p for p in reversed(parts[:-1]))

def compare(a, b):
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return -1 if a < b else (1 if a > b else 0)

def main():
    act, a, b = sys.stdin.read().split()
    print(add(a, b) if act == 'add' else compare(a, b))

main()

