def gen(rng):
    def num(k):
        if k == 1:
            return str(rng.randint(0, 9))
        return str(rng.randint(1, 9)) + ''.join(rng.choice('0123456789') for _ in range(k - 1))
    def fmt(act, a, b):
        return f'{act}\n{a}\n{b}'
    tests = []
    for act in ('add', 'compare'):
        tests += [fmt(act, '0', '0'), fmt(act, '0', '5'), fmt(act, '9', '1'), fmt(act, '9999', '1'), fmt(act, '10000', '9999'),
                  fmt(act, '12345678', '99999999'), fmt(act, '123456789', '99999999'), fmt(act, '100000000', '100000000'),
                  fmt(act, '12349999', '99991111'), fmt(act, '99999', '99999')]
    for _ in range(14):
        for act in ('add', 'compare'):
            tests.append(fmt(act, num(rng.randint(1, 14)), num(rng.randint(1, 14))))
    n = 100000
    nines = '9' * n
    tests.append(fmt('add', nines, '1'))
    tests.append(fmt('add', num(n), num(n)))
    tests.append(fmt('add', num(n), num(n // 3)))
    a = num(n)
    tests.append(fmt('compare', a, a))
    tests.append(fmt('compare', a[:-1] + ('1' if a[-1] != '1' else '2'), a))
    tests.append(fmt('compare', num(n), num(n - 1)))
    tests.append(fmt('add', nines, nines))
    return tests

